export interface LtmEntry {
  /** 记忆 ID */
  id: string
  /** 记忆文本 */
  text: string
  /** 记忆类型（fact/plan/preference/event/note） */
  memory_type: string
  /** 重要性 1-10 */
  poignancy: number
  /** Unix 时间戳 */
  timestamp: number
  /** 附加元数据，可缺省 */
  metadata?: Record<string, unknown>
}

/** /debug/api/ltm 列表响应。 */
export interface LtmListResponse {
  /** 命中总数 */
  total: number
  /** 当前页条目 */
  entries: LtmEntry[]
}

/** Debug 增删改操作通用结果（ok 判别 + 可选计数）。 */
export interface DebugResult {
  /** 操作是否成功 */
  ok: boolean
  /** 删除/清空计数，可缺省 */
  deleted?: number
  /** 同步清理的 session 消息数，可缺省 */
  session_purged?: number
}

/** 角色版本回滚结果。 */
export interface RollbackResult {
  /** 状态（恒为 ok） */
  status: string
  /** 回滚产生的新版本号 */
  new_version: number
  /** 恢复的版本文本 */
  text: string
}

/** 归档消息分页响应（messages 复用 rest.Message 契约视图）。 */
export interface ArchiveListResponse {
  /** 归档消息列表 */
  messages: Message[]
  /** 总消息数 */
  total: number
  /** 每页条数 */
  limit: number
  /** 偏移量 */
  skip: number
}

/** 会话列表条目。 */
export interface SessionInfo {
  /** 会话 ID */
  session_id: string
  /** 消息条数 */
  message_count: number
  /** 最近更新时间 ISO 字符串 */
  updated_at: string
  /** token 总用量 */
  token_total: number
}

/** 会话列表响应。 */
export interface SessionListResponse {
  /** 会话条目列表 */
  sessions: SessionInfo[]
}

/** 会话详情单条消息（契约视图；兼容 sessions_to_client 与 messages_for_client 两来源）。 */
export interface SessionDetailMessage {
  /** 消息角色（user/assistant/tool） */
  role: string
  /** ISO 时间戳，可缺省 */
  timestamp?: string
  /** 内容类型 → 序号映射，可缺省 */
  content_type?: Record<string, unknown>
  /** 纯文本 parts 列表 */
  parts: DebugSessionPart[]
  /** 消息内容（文本或内容块列表） */
  content: unknown
}

/** 会话详情响应。 */
export interface SessionDetailResponse {
  /** 会话 ID */
  session_id: string
  /** 消息列表 */
  messages: SessionDetailMessage[]
  /** 角色状态参数，可缺省 */
  params?: Record<string, unknown>
  /** 消息总数（归档源时存在），可缺省 */
  total?: number
}

/** 完整 prompt 记录详情。 */
export interface PromptDetail {
  /** 记录序号 */
  index: number
  /** ISO 时间戳 */
  timestamp: string
  /** 轮次序号 */
  round_num: number
  /** 模型名 */
  model: string
  /** LLM 消息列表 */
  messages: unknown[]
  /** 工具定义列表 */
  tools: unknown[]
  /** 模板源码（path + sections），可缺省 */
  template_source?: Record<string, unknown>
}

/** 完整原始回复详情。 */
export interface ResponseDetail {
  /** 记录序号 */
  index: number
  /** ISO 时间戳 */
  timestamp: string
  /** 轮次序号 */
  round_num: number
  /** 原始回复文本 */
  raw_text: string
  /** 内心独白，可缺省 */
  inner_voice?: string
  /** 回复文本长度 */
  text_len: number
  /** 内心独白长度 */
  inner_voice_len: number
}

/** 角色版本历史列表响应（versions 保留 VersionEntry 全部 wire 键）。 */
export interface CharacterVersionListResponse {
  /** 版本条目列表 */
  versions: unknown[]
  /** 版本总数 */
  total: number
  /** 是否还有更早版本 */
  has_more: boolean
}

/** 任务 DAG 节点。 */
export interface TaskNode {
  /** 节点 ID */
  node_id: string
  /** 节点状态 */
  status: string
  /** 尝试次数 */
  attempt: number
  /** 节点摘要 */
  summary: string
  /** 节点错误，可缺省 */
  error?: string
}

/** 任务快照条目（TasksTab；workflow_engine 快照 wire 形状 + 前端 title 展示字段）。 */
export interface TaskData {
  /** 任务 ID */
  task_id: string
  /** 任务状态 */
  status: string
  /** 任务标题（前端展示用），可缺省 */
  title?: string
  /** 计划版本号 */
  plan_version: number
  /** 创建时间，可缺省 */
  created_at?: string
  /** 任务错误，可缺省 */
  error?: string
  /** 任务错误码，可缺省 */
  error_code?: string
  /** 当前执行阶段 */
  phase: string
  /** 邮箱待处理消息数 */
  mailbox_depth: number
  /** DAG 节点列表 */
  nodes: TaskNode[]
  /** DAG 边列表 [from, to] */
  edges: string[][]
}

export type ServerMessage =
  | SessionMessage
  | CapabilitiesMessage
  | ServerInfoMessage
  | DeltaMessage
  | MessageMessage
  | TokenUsageMessage
  | ExpressionMessage
  | StateMessage
  | AudioMessage
  | AudioEndMessage
  | TypingMessage
  | TranscriptionMessage
  | ActionMessage
  | CommandMessage
  | WakeMessage
  | SwitchModelResultMessage
  | ServiceModeResultMessage
  | HeartbeatAckMessage
  | ErrorMessage
  | UserAckMessage
  | GenerationStartedMessage
  | GenerationSegmentStartedMessage
  | GenerationDeltaMessage
  | GenerationSegmentCompletedMessage
  | GenerationCompletedMessage
  | GenerationFailedMessage
  | UnknownMessage

export interface UnknownMessage { type: string; [key: string]: unknown }
